create table if not exists public.tedvio_legal_documents(document_key text not null,version text not null,title text not null,summary text,content_html text not null,effective_at timestamptz not null default now(),required boolean not null default true,status text not null default 'published' check(status in('draft','published','archived')),created_at timestamptz not null default now(),primary key(document_key,version));
create table if not exists public.tedvio_user_consents(id uuid primary key default gen_random_uuid(),user_id uuid not null,document_key text not null,document_version text not null,accepted_at timestamptz not null default now(),source text not null default 'account_center',created_at timestamptz not null default now(),unique(user_id,document_key,document_version));
create index if not exists tedvio_user_consents_user_idx on public.tedvio_user_consents(user_id,accepted_at desc);
create table if not exists public.tedvio_account_deletion_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null,status text not null default 'pending' check(status in('pending','cancelled','completed')),reason text,requested_at timestamptz not null default now(),scheduled_for timestamptz not null default(now()+interval '30 days'),cancelled_at timestamptz,completed_at timestamptz,updated_at timestamptz not null default now());
create unique index if not exists tedvio_account_deletion_one_pending_idx on public.tedvio_account_deletion_requests(user_id) where status='pending';
create index if not exists tedvio_account_deletion_user_idx on public.tedvio_account_deletion_requests(user_id,requested_at desc);
create table if not exists public.tedvio_data_export_audit(id uuid primary key default gen_random_uuid(),user_id uuid not null,format text not null default 'json',status text not null default 'completed' check(status in('started','completed','failed')),requested_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now());
create index if not exists tedvio_data_export_user_idx on public.tedvio_data_export_audit(user_id,requested_at desc);
alter table public.tedvio_legal_documents enable row level security;alter table public.tedvio_user_consents enable row level security;alter table public.tedvio_account_deletion_requests enable row level security;alter table public.tedvio_data_export_audit enable row level security;
drop policy if exists tedvio_legal_published_select on public.tedvio_legal_documents;create policy tedvio_legal_published_select on public.tedvio_legal_documents for select to authenticated using(status='published');
drop policy if exists tedvio_consents_self_select on public.tedvio_user_consents;create policy tedvio_consents_self_select on public.tedvio_user_consents for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists tedvio_deletion_self_select on public.tedvio_account_deletion_requests;create policy tedvio_deletion_self_select on public.tedvio_account_deletion_requests for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists tedvio_export_self_select on public.tedvio_data_export_audit;create policy tedvio_export_self_select on public.tedvio_data_export_audit for select to authenticated using(user_id=(select auth.uid()));
grant select on public.tedvio_legal_documents,public.tedvio_user_consents,public.tedvio_account_deletion_requests,public.tedvio_data_export_audit to authenticated;revoke all on public.tedvio_legal_documents,public.tedvio_user_consents,public.tedvio_account_deletion_requests,public.tedvio_data_export_audit from anon;revoke insert,update,delete on public.tedvio_user_consents,public.tedvio_account_deletion_requests,public.tedvio_data_export_audit from authenticated;
create schema if not exists tedvio_private;
create or replace function tedvio_private.accept_legal_v69(p_document_key text,p_document_version text,p_source text default 'account_center') returns public.tedvio_user_consents language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=auth.uid();v_doc public.tedvio_legal_documents;v_row public.tedvio_user_consents;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_doc from public.tedvio_legal_documents where document_key=p_document_key and version=p_document_version and status='published';if v_doc.document_key is null then raise exception 'LEGAL_DOCUMENT_NOT_FOUND';end if;insert into public.tedvio_user_consents(user_id,document_key,document_version,accepted_at,source) values(v_uid,v_doc.document_key,v_doc.version,now(),left(coalesce(nullif(btrim(p_source),''),'account_center'),80)) on conflict(user_id,document_key,document_version) do update set accepted_at=excluded.accepted_at,source=excluded.source returning * into v_row;return v_row;end$$;
create or replace function public.tedvio_accept_legal_v69(p_document_key text,p_document_version text,p_source text default 'account_center') returns public.tedvio_user_consents language sql security invoker set search_path=public,tedvio_private,pg_temp as $$select tedvio_private.accept_legal_v69(p_document_key,p_document_version,p_source);$$;
create or replace function tedvio_private.request_account_deletion_v69(p_reason text default null) returns public.tedvio_account_deletion_requests language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=auth.uid();v_row public.tedvio_account_deletion_requests;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_row from public.tedvio_account_deletion_requests where user_id=v_uid and status='pending' order by requested_at desc limit 1;if v_row.id is not null then return v_row;end if;insert into public.tedvio_account_deletion_requests(user_id,status,reason,requested_at,scheduled_for,updated_at) values(v_uid,'pending',nullif(left(btrim(coalesce(p_reason,'')),500),''),now(),now()+interval '30 days',now()) returning * into v_row;return v_row;end$$;
create or replace function public.tedvio_request_account_deletion_v69(p_reason text default null) returns public.tedvio_account_deletion_requests language sql security invoker set search_path=public,tedvio_private,pg_temp as $$select tedvio_private.request_account_deletion_v69(p_reason);$$;
create or replace function tedvio_private.cancel_account_deletion_v69() returns public.tedvio_account_deletion_requests language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=auth.uid();v_row public.tedvio_account_deletion_requests;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;update public.tedvio_account_deletion_requests set status='cancelled',cancelled_at=now(),updated_at=now() where id=(select id from public.tedvio_account_deletion_requests where user_id=v_uid and status='pending' order by requested_at desc limit 1) returning * into v_row;return v_row;end$$;
create or replace function public.tedvio_cancel_account_deletion_v69() returns public.tedvio_account_deletion_requests language sql security invoker set search_path=public,tedvio_private,pg_temp as $$select tedvio_private.cancel_account_deletion_v69();$$;
create or replace function public.tedvio_account_center_snapshot_v69() returns jsonb language sql security invoker set search_path=public,pg_temp as $$with me as(select auth.uid() uid),docs as(select d.document_key,d.version,d.title,d.summary,d.effective_at,d.required,exists(select 1 from public.tedvio_user_consents c,me where c.user_id=me.uid and c.document_key=d.document_key and c.document_version=d.version) accepted from public.tedvio_legal_documents d where d.status='published' and d.version=(select d2.version from public.tedvio_legal_documents d2 where d2.document_key=d.document_key and d2.status='published' order by d2.effective_at desc,d2.version desc limit 1)),memberships as(select m.institution_id,m.member_role,m.status,i.name from public.tedvio_institution_memberships m join public.tedvio_institutions i on i.id=m.institution_id,me where m.user_id=me.uid and m.status='active'),blockers as(select m.institution_id,i.name from public.tedvio_institution_memberships m join public.tedvio_institutions i on i.id=m.institution_id,me where m.user_id=me.uid and m.status='active' and m.member_role='institution_admin' and not exists(select 1 from public.tedvio_institution_memberships x where x.institution_id=m.institution_id and x.status='active' and x.member_role='institution_admin' and x.user_id<>me.uid)),del as(select * from public.tedvio_account_deletion_requests,me where user_id=me.uid and status='pending' order by requested_at desc limit 1) select jsonb_build_object('profile',(select to_jsonb(p)-'user_id' from public.tedvio_user_profiles p,me where p.user_id=me.uid),'documents',coalesce((select jsonb_agg(to_jsonb(d) order by d.document_key) from docs d),'[]'::jsonb),'memberships',coalesce((select jsonb_agg(to_jsonb(m) order by m.name) from memberships m),'[]'::jsonb),'deletion_blockers',coalesce((select jsonb_agg(to_jsonb(b) order by b.name) from blockers b),'[]'::jsonb),'pending_deletion',(select to_jsonb(d)-'user_id' from del d),'export_count',(select count(*) from public.tedvio_data_export_audit e,me where e.user_id=me.uid and e.status='completed'));$$;
revoke all on function tedvio_private.accept_legal_v69(text,text,text),tedvio_private.request_account_deletion_v69(text),tedvio_private.cancel_account_deletion_v69() from public,anon;grant execute on function tedvio_private.accept_legal_v69(text,text,text),tedvio_private.request_account_deletion_v69(text),tedvio_private.cancel_account_deletion_v69() to authenticated;revoke all on function public.tedvio_accept_legal_v69(text,text,text),public.tedvio_request_account_deletion_v69(text),public.tedvio_cancel_account_deletion_v69(),public.tedvio_account_center_snapshot_v69() from public,anon;grant execute on function public.tedvio_accept_legal_v69(text,text,text),public.tedvio_request_account_deletion_v69(text),public.tedvio_cancel_account_deletion_v69(),public.tedvio_account_center_snapshot_v69() to authenticated;
